def codex_plan():
    """Gói ChatGPT ghi trong file đăng nhập Codex (free, plus, pro, team...). '' = không rõ."""
    f = Path(os.environ.get("CODEX_HOME") or Path.home() / ".codex") / "auth.json"
    toks = (rjson(f) or {}).get("tokens") or {}
